// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Prior-auth agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize request').item.json;
if (out) {
  if (!out.patient_found) reasons.push('patient not found');
  if (!out.coverage_active) reasons.push('coverage not active on requested date');
  if (out.pa_required === 'unknown') reasons.push('could not determine whether PA is required');
  if (out.urgency_assessment !== req.requested_urgency) {
    reasons.push('urgency: office asked ' + req.requested_urgency + ', agent assessed ' + out.urgency_assessment);
  }
  const unsourced = (out.packet ?? []).filter((p) => p.status === 'present' && !p.source);
  if (unsourced.length) reasons.push(unsourced.length + ' packet items marked present without a source');
  if (out.route_queue === 'ready_for_submission_review' && (out.packet ?? []).some((p) => p.status !== 'present')) {
    reasons.push('marked ready but packet has missing or unclear items');
  }
}

const ok = reasons.length === 0;
return {
  json: {
    business_key: req.business_key,
    route: ok ? 'auto' : 'escalate',
    guardrail_reasons: reasons,
    planned_actions: ok ? [{ action: 'worklist.insert', queue: out.route_queue, urgency: out.urgency_assessment }] : [],
  },
};

const planned = $('Prior-auth agent').item.json.output;
const ok = !!$json.id && $json.queue === planned.route_queue && $json.urgency === planned.urgency_assessment;
return {
  json: {
    verified: ok,
    verify_failed: !ok,
    verify_detail: ok ? '' : 'worklist row does not match the planned queue and urgency',
    worklist_id: $json.id,
    queue: $json.queue,
    urgency: $json.urgency,
  },
};

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize request').item.json;
let agent = null;
let guard = null;
try { agent = $('Prior-auth agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "PA intake coordinators",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'PA request ' + intake.request_id + ' · proposed queue: ' + (agent?.output?.route_queue ?? 'none') + ' · urgency: ' + (agent?.output?.urgency_assessment ?? intake.requested_urgency),
  },
};

